-- The worldserver loads the DBC set the players' client runs. A `*_dbc` row replaces the loaded client row with
-- the same index, so these rows either repeated client data or replaced CoA values with stock 3.3.5a data.

-- Stock game tables from ACDB. They replaced 535 of the client's 3,200 combat rating conversions (resilience,
-- armor penetration and low-level crit included), 95 of 100 NPC mana cost scalers and the crit and regeneration
-- rows of classes 1-11. With them gone every class reads the client's rows, as classes 12-32 already did.
DELETE FROM `gtbarbershopcostbase_dbc`;
DELETE FROM `gtchancetomeleecrit_dbc`;
DELETE FROM `gtchancetomeleecritbase_dbc`;
DELETE FROM `gtchancetospellcrit_dbc`;
DELETE FROM `gtchancetospellcritbase_dbc`;
DELETE FROM `gtcombatratings_dbc`;
DELETE FROM `gtnpcmanacostscaler_dbc`;
DELETE FROM `gtoctclasscombatratingscalar_dbc`;
DELETE FROM `gtoctregenhp_dbc`;
DELETE FROM `gtregenhpperspt_dbc`;
DELETE FROM `gtregenmpperspt_dbc`;

-- All 841 stock faction templates exist in the client; six carried different flags, friends or enemies.
DELETE FROM `factiontemplate_dbc`;

-- Copies of client rows, added while the server's DBC extract lacked them.
DELETE FROM `creaturedisplayinfo_dbc` WHERE `ID` IN (7654, 93307, 236827);
DELETE FROM `creaturemodeldata_dbc` WHERE `ID` IN (8088, 10899, 110722);
DELETE FROM `currencytypes_dbc` WHERE `ItemID` = 375250;

